// Ambil payload dari trigger Webhook
let inputData = $input.first().json;
let payload = inputData.body || inputData;

// Deteksi penumpukan struktur JSON dari Python (nested body)
if (payload.body && payload.body.application_id) {
    payload = payload.body;
}

const options = payload.data?.options || [];

let satuan = 'd';
let angka = 1;
let min_level = 0;
let max_level = 15;

for (const opt of options) {
  if (opt.name === 'satuan_waktu') satuan = opt.value;
  if (opt.name === 'angka_waktu') angka = parseInt(opt.value);
  if (opt.name === 'level_minimal') min_level = parseInt(opt.value);
  if (opt.name === 'level_maksimal') max_level = parseInt(opt.value);
}

// Keamanan filter
if (angka < 1) angka = 1;
if (min_level < 0) min_level = 0;
if (max_level > 15) max_level = 15;
if (min_level > max_level) {
    let temp = min_level; min_level = max_level; max_level = temp;
}

const time_query = `${angka}${satuan}`;
const satuan_label = satuan === 'h' ? 'Jam' : 'Hari';
const label_waktu = `${angka} ${satuan_label} Terakhir`;
const label_level = (min_level === 0 && max_level === 15) ? "Semua Level" : `Level ${min_level} - ${max_level}`;

return [{
  json: {
    app_id: payload.application_id || "",
    token: payload.token || "",
    time_query: time_query,
    label_waktu: label_waktu,
    min_level: min_level,
    max_level: max_level,
    label_level: label_level
  }
}];

const response = $input.first().json;
const hits = (response.hits && response.hits.hits) ? response.hits.hits.map(h => h._source) : [];

let counts = { critical: 0, high: 0, medium: 0, low: 0, total: hits.length };
let ruleSummary = {}; let ipSummary = {}; let agentSummary = {};
let sampleHighAlerts = []; let sampleMedAlerts = [];

hits.forEach(alert => {
  const lvl = alert.rule?.level || 0;
  const ruleId = alert.rule?.id || "unknown";
  const ruleDesc = alert.rule?.description || "No description";
  const agentName = alert.agent?.name || "Unknown Agent";
  const agentIp = alert.agent?.ip || "-";
  const srcIp = alert.data?.srcip || alert.srcip || null;

  if (lvl >= 12) counts.critical++;
  else if (lvl >= 8) counts.high++;
  else if (lvl >= 4) counts.medium++;
  else counts.low++;

  const ruleKey = `Rule ${ruleId}: ${ruleDesc}`;
  ruleSummary[ruleKey] = (ruleSummary[ruleKey] || 0) + 1;

  const agentKey = `${agentName} (${agentIp})`;
  agentSummary[agentKey] = (agentSummary[agentKey] || 0) + 1;

  if (srcIp && srcIp !== "-" && srcIp !== "127.0.0.1") {
    ipSummary[srcIp] = (ipSummary[srcIp] || 0) + 1;
  }

  if (lvl >= 8 && sampleHighAlerts.length < 15) {
    sampleHighAlerts.push({ timestamp: alert.timestamp, rule_id: ruleId, level: lvl, description: ruleDesc, agent: `${agentName} (${agentIp})`, srcip: srcIp || "N/A" });
  } else if (lvl >= 4 && lvl < 8 && sampleMedAlerts.length < 10) {
    sampleMedAlerts.push({ timestamp: alert.timestamp, rule_id: ruleId, level: lvl, description: ruleDesc, agent: `${agentName} (${agentIp})`, srcip: srcIp || "N/A" });
  }
});

return [{
  json: {
    counts,
    topRules: Object.entries(ruleSummary).sort((a, b) => b[1] - a[1]).slice(0, 5),
    topIps: Object.entries(ipSummary).sort((a, b) => b[1] - a[1]).slice(0, 5),
    topAgents: Object.entries(agentSummary).sort((a, b) => b[1] - a[1]).slice(0, 5),
    sampleHighAlerts,
    sampleMedAlerts
  }
}];

